# Translations for strings localized in code via L10n.t / L10n.f (keys = English source).
# Columns: uk, de, es, fr, it, pt-BR, ja, ko, zh-Hans, zh-Hant, tr
S = {}
def T(key, *v):
    assert len(v) == 11, key
    S[key] = v

def UK(key, one, few, many):
    """Ukrainian plural forms for a key already defined with T()."""
    v = list(S[key]); v[0] = {"one": one, "few": few, "many": many, "other": many}; S[key] = tuple(v)

